(function orderGrammar() {
  const order = [1, 2, 3, 13, 4, 5, 6, 7, 14, 8, 15, 11, 12, 16, 9, 10, 17, 18];
  grammarTopics.sort((a, b) => order.indexOf(a.id) - order.indexOf(b.id));
})();

