function nextUnitFor(p) {
  const start = p.placement ? p.placement.level : 1;
  const order = UNITS.filter((u) => u.level >= start).concat(UNITS.filter((u) => u.level < start));
  return order.find((u) => !(p.units[u.id] && p.units[u.id].stars > 0)) || order.find((u) => (p.units[u.id] || {}).stars < 3) || UNITS[0];
}
/* Today's plan = the daily play flow: (1) the next Journey unit, (2) a power-up for the skill that needs it most
   (catch-up, framed positively), (3) a talk-or-read moment (alternates by day). The Play button walks through it. */
function todaysPlan(p) {
  const plan = [];
  if (!p.placement) plan.push({ id: 'placement', icon: '🧭', ar: 'لُعْبَة البِدَايَة', en: '2-minute starting game', act: 'placement-start', done: !!p.placement });
  else { const u = nextUnitFor(p); plan.push({ id: 'unit', icon: u.icon, ar: 'رِحْلَتِي: ' + u.ar, en: 'Journey: ' + u.en, act: 'open-unit', arg: u.id, done: !!p.today.cats.unit }); }
  const f = focusSkill(p); const B = BOOST[f];
  plan.push({ id: 'boost', icon: '⚡', ar: 'قُوَّة إِضَافِيَّة: ' + B.ar, en: 'Power-up: ' + B.en + ' (' + SKILL[f].en + ')', act: 'boost', arg: f, done: !!p.today.cats.boost });
  const readDay = hashStr(p.today.d + currentKid) % 2 === 0 && f !== 'reading';
  if (readDay || f === 'speaking') { const st = nextReadStory(p); plan.push({ id: 'readaloud', icon: '📖', ar: G('اِقْرَأْ', 'اِقْرَئِي') + ' بِصَوْت: ' + st.title, en: 'Read aloud: ' + st.en, act: 'read-open', arg: st.id, done: !!p.today.cats.read }); }
  else plan.push({ id: 'sayit', icon: '🎤', ar: G('قُلْهَا', 'قُولِيهَا') + ' بِصَوْتٍ عَالٍ', en: 'Say it out loud (3 phrases)', act: 'sayit-open', done: !!p.today.cats.say });
  return plan;
}
function checkQuests() {
  const p = P();
  const plan = todaysPlan(p);
  plan.forEach((q) => { if (q.done && !p.today.quests[q.id]) { p.today.quests[q.id] = true; p.coins += 10; toast(`✅ مُهِمَّة اليَوْم! +10 <i class="ci"></i> <span class="en">Quest done: ${esc(q.en)}</span>`); sfx('coin'); } });
  if (!p.today.planBonus && plan.every((q) => q.done)) {
    p.today.planBonus = true; p.coins += 25; confetti(160); sfx('level');
    toast('🎉 ' + G('أَنْهَيْتَ', 'أَنْهَيْتِ') + ' خُطَّةَ اليَوْم! +25 <i class="ci"></i> <span class="en">Today\'s plan complete!</span>', 3200);
  }
  WEEKLY.forEach((w) => { if (!p.weekly.claimed[w.id] && (p.weekly.c[w.key] || 0) >= w.goal) { p.weekly.claimed[w.id] = true; p.coins += w.reward; sfx('coin'); toast(`🏆 مُهِمَّة الأُسْبُوع! +${w.reward} <i class="ci"></i> <span class="en">Weekly quest: ${esc(w.en)}</span>`, 3000); } });
}

/* =========================================================
   REWARDS: XP + coins only come from learning actions
   ========================================================= */
function award(xp, cat, opts) {
  opts = opts || {};
  const p = P(); rollover(p);
  const before = levelInfo(p.xp).lvl;
  const t = dayKey();
  if (!p.activeDays.includes(t)) { p.activeDays.push(t); setTimeout(streakBurst, 350); if (p.activeDays.length > 800) p.activeDays = p.activeDays.slice(-800); p.weekly.c.days++; }
  if (!p.today.streakReward) {
    p.today.streakReward = true; const st = computeStreak(p.activeDays); const bonus = 5 + Math.min(st, 7) * 2;
    p.coins += bonus; setTimeout(() => toast(`<i class="fi"></i> ${toArabicDigits(st)} ${st === 1 ? 'يَوْم' : 'أَيَّام'}! +${bonus} <i class="ci"></i> <span class="en">Daily streak reward (day ${st})</span>`, 2800), 300);
  }
  if (xp > 0) {
    p.xp += xp; const coins = Math.ceil(xp / 2); p.coins += coins; flyReward(xp, coins);
    p.xpByDay[t] = (p.xpByDay[t] || 0) + xp; p.weekly.c.xp += xp;
    if (!opts.quiet) { toast(`+${xp} <i class="pi"></i> · +${coins} <i class="ci"></i> ${opts.msg ? '· ' + opts.msg : ''}`); sfx('coin'); }
  }
  if (cat) p.today.cats[cat] = true;
  checkQuests(); checkBadges();
  const after = levelInfo(p.xp).lvl;
  saveDB(); refreshHeader();
  if (after > before) setTimeout(() => celebrateLevel(after), 500);
  if (currentTab === 'home') renderHome();
}
/* award once per key (no farming) */
function completeOnce(key, xp, cat, msg) {
  const p = P(); if (p.completed[key]) { if (cat) { p.today.cats[cat] = true; checkQuests(); saveDB(); } return false; }
  p.completed[key] = dayKey(); award(xp, cat, { msg }); return true;
}
function celebrateLevel(lvl) {
  /* never interrupt an open activity sheet: celebrate as soon as it closes */
  if (!$('modal').classList.contains('hidden') && !$('modal').classList.contains('celebrate')) { pendingLevel = Math.max(pendingLevel, lvl); return; }
  const t = LEVEL_TITLES[lvl - 1]; sfx('level'); confetti(200);
  /* v7: reaching a new falcon tier: the colour softly changes inside the card */
  let bird = falconSVG('celebrate', 'lg'); let tierHTML = '';
  if (currentKid && typeof falconTierIndex === 'function') {
    const f = P().falcon; const ti = falconTierIndex(lvl); const seen = typeof f.tierSeen === 'number' ? f.tierSeen : 0;
    if (ti > seen) {
      const nt = FALCON_TIERS[ti]; const old = FALCON_TIERS[Math.min(seen, FALCON_TIERS.length - 1)]; f.tierSeen = ti; saveDB();
      if (f.follow !== false) bird = `<span class="tier-morph">${falconSVG('look', 'lg tm-old', Object.assign(falconCfg(), { pal: old.pal, outfit: null }))}${falconSVG('look', 'lg tm-new', Object.assign(falconCfg(), { pal: nt.pal, outfit: null }))}</span>`;
      tierHTML = `<div class="cel-tier"><span class="cel-tier-sw pal-sw-${nt.pal}"></span><span><b>${nt.ar}</b> <span class="en">${f.follow !== false ? `Your falcon grew into a ${esc(nt.en)}!` : `New colour unlocked: ${esc(nt.en)}. Find it in My falcon.`}</span></span></div>`;
    }
  }
  openModal(`<div class="celebrate-inner center">${typeof sceneBg === 'function' ? sceneBg('dubai_skyline', 'cel-scene') : ''}
    <div class="cel-bird">${bird}<div class="lvl-star"><b>${toArabicDigits(lvl)}</b></div></div>
    <div class="cel-kicker">المُسْتَوَى ${toArabicDigits(lvl)}</div>
    <h2 class="cel-title">مَبْرُوك</h2>
    <p class="cel-sub">${G('أَنْتَ', 'أَنْتِ')} الآن «${esc(t[0])}» <span class="en en-block">Level ${lvl}. You're now ${/^[AEIOU]/.test(t[1]) ? 'an' : 'a'} ${esc(t[1])}. New shop items may unlock.</span></p>
    ${tierHTML}
    <button class="btn big" data-act="modal-close">رَائِع <span class="en">Great</span></button></div>`, null, 'celebrate');
}

