function readerPaint() { const pg = $('ra-page'); if (!pg || !reader) return; pg.querySelectorAll('.ra-w').forEach((el) => { const i = Number(el.dataset.i); el.classList.toggle('hi', reader.hi === i); el.classList.toggle('got', !!reader.read[i]); }); const hi = pg.querySelector('.ra-w.hi'); if (hi && hi.scrollIntoView) hi.scrollIntoView({ block: 'nearest', behavior: reducedMotion() ? 'auto' : 'smooth' }); }
