    const text = r.st.s[si][0]; const base = sIdx(si); const n = text.split(/\s+/).length; let gotB = false; let k = 0;
    const starts = []; let pos = 0; text.split(/\s+/).forEach((w) => { const at = text.indexOf(w, pos); starts.push(at); pos = at + w.length; });
