      recog.onresult = (ev) => {
        let txt = ''; for (let i = 0; i < ev.results.length; i++) txt += ' ' + ev.results[i][0].transcript;
        const heard = txt.split(/\s+/).map(norm).filter(Boolean); let changed = false; const firstOpen = r.words.findIndex((w, i) => !r.read[i]);
        r.words.forEach((w, i) => { if (r.read[i] || i > firstOpen + 12) return; const t = norm(w.w); const t2 = t.replace(/^(ال|و|ف|ب|ل)/, ''); if (heard.some((h) => h === t || (t2.length > 2 && h.includes(t2)) || (h.length > 2 && t.includes(h) && h.length >= t.length - 2))) { r.read[i] = true; changed = true; } });
        if (changed) { r.hi = r.words.findIndex((w, i) => !r.read[i]); readerPaint(); sfx('pop'); const pr = document.querySelector('.reader .progress > div'); if (pr) pr.style.width = Math.round((100 * Object.keys(r.read).length) / r.words.length) + '%'; }
      };
