  openModal(`<div class="center stack">${mascotSVG('trophy lg')}<h2 class="ar-big" style="font-size:1.5rem">${G('قَارِئٌ رَائِع', 'قَارِئَةٌ رَائِعَة')}! 📖</h2><p class="en en-block center">You read “${esc(r.st.en)}” out loud. Reading aloud every day makes your Arabic grow fast!</p>
    <div class="row" style="justify-content:center"><button class="btn ghost" data-act="read-open" data-arg="${r.st.id}">🔁 <span class="en">Read again</span></button><button class="btn gold" data-act="modal-close">رَائِع! <span class="en">Awesome!</span></button></div></div>`, () => { if (currentTab === 'home') renderHome(); if (currentTab === 'stories') RENDER.stories(); }, 'sheet');
