/* =========================================================
   LISTEN & TAP: hear a word, tap its picture (listening power-up)
   ========================================================= */
let lround = null;
function listenStart() {
  const pool = gamePool(); const qs = sample(pool, 6).map((w) => ({ w, opts: shuffle([w].concat(sample(pool.filter((x) => x.em !== w.em), 3))) }));
  lround = { qs, i: 0, score: 0, a: null, audio: hasTTS && !!SPEECH.resolve('fusha').voice }; renderListen(); if (lround.audio) setTimeout(() => lround && speak(lround.qs[0].w.ar, 'fusha'), 300);
}
function renderListen() {
  const L = lround; const q = L.qs[L.i]; const a = L.a;
  openModal(`<div class="stack listen-round">
    <div class="row between"><span class="pill acc">👂 ${L.i + 1}/${L.qs.length}</span><span class="pill good">✓ ${L.score}</span>${closeBtn()}</div>
    <div class="center stack">${L.audio ? '<button class="speaker-btn" data-act="lr-play" aria-label="Play word"><span>🔊</span><b>اِسْتَمِعْ <span class="en">Listen</span></b></button>' : `<p class="en en-block center">🔇 No Arabic voice here, so read the word instead:</p><div class="ar-big">${esc(q.w.ar)}</div>`}
      <p class="en en-block center">Tap the picture you hear.</p></div>
    <div class="pic-opts">${q.opts.map((o, i) => { let c = ''; if (a !== null) c = o === q.w ? 'right' : i === a ? 'wrong' : 'dim'; return `<button class="opt pic ${c}" data-act="lr-pick" data-arg="${i}" ${a !== null ? 'disabled' : ''}><span class="pic-em">${o.em}</span>${a !== null ? `<span class="en">${esc(o.en)}</span>` : ''}</button>`; }).join('')}</div>
    ${a !== null ? `<div class="row between lr-fb ${q.opts[a] === q.w ? 'good' : 'bad'}"><b>${q.opts[a] === q.w ? pickPraise() : `${esc(q.w.ar)} = ${q.w.em} <span class="en">${esc(q.w.en)}</span>`}</b><button class="btn" data-act="lr-next">التَّالِي <span class="en">Next</span></button></div>` : ''}
  </div>`, () => { lround = null; }, 'sheet');
}
function listenPick(i) {
  const L = lround; if (!L || L.a !== null) return; L.a = Number(i); const ok = L.qs[L.i].opts[L.a] === L.qs[L.i].w;
  if (ok) { L.score++; sfx('good'); } else sfx('bad'); skillHit(L.audio ? 'listening' : 'reading', ok); saveDB(); renderListen();
}
