    const s = L.score; const t = P().today; t.games.lr = (t.games.lr || 0) + 1; modalOnClose = null; lround = null; closeModal();
    award(s >= 4 && t.games.lr <= 3 ? 12 : 0, s >= 4 ? 'game' : null, { msg: '👂' }); if (s >= 4) confetti(100);
    openModal(`<div class="center stack">${mascotSVG(s >= 4 ? 'cheer lg' : 'think lg')}<h2 class="ar-big">${toArabicDigits(s)}/${toArabicDigits(6)}</h2><p class="en en-block center">${s >= 4 ? 'Super ears! 👂' : 'Good listening practice. Every try makes your ears sharper!'}</p><div class="row" style="justify-content:center"><button class="btn ghost" data-act="lr-again">🔁 <span class="en">Again</span></button><button class="btn gold" data-act="modal-close">👍 <span class="en">Done</span></button></div></div>`, null, 'sheet');
