    <div class="skill-orbs">${SKILLS.map((s) => { const sc = skillScore(p, s.id); const b = skillBand(sc); const k = BAND_KID[b]; const fill = sc == null ? 0.12 : Math.max(0.15, sc);
      return `<button class="orb ${b} ${s.id === f ? 'focus-now' : ''}" data-act="boost" data-arg="${s.id}" style="--sc:${s.color};--f:${fill}"><span class="orb-ring"><span class="orb-ic">${s.icon}</span></span><span class="orb-nm">${s.ar}</span><span class="en orb-en">${esc(s.en)}</span><span class="orb-tag">${k[0]} <span class="en">${k[2]}</span></span></button>`; }).join('')}</div>
