  const prevTab = currentTab; currentTab = id; closeMore(); closeMenu();
  if (prevTab !== id && !$('app').classList.contains('hidden')) archWipe();
  document.body.dataset.tab = id;
  document.querySelectorAll('.tab').forEach((el) => el.classList.add('hidden'));
