  const s = $('sound-btn'); if (s) { s.innerHTML = DB.settings.sound ? '🔊 <span class="en">Sound: on</span>' : '🔇 <span class="en">Sound: off</span>'; s.title = DB.settings.sound ? 'Sound on' : 'Sound off'; }
