function closeMenu() { const m = $('menu'); if (m) m.classList.add('hidden'); const b = $('menu-btn'); if (b) b.setAttribute('aria-expanded', 'false'); }
function kidFace(id) { const p = DB.kids[id]; const f = p.shop.face && SHOP.find((i) => i.id === p.shop.face); return avatarHTML(id, 'sm'); }

