    <div class="steps" style="--si:${si}">${steps.map((st, i) => `<button class="step ${st[0] === s ? 'active' : ''} ${st[4] ? 'ok' : ''}" data-act="unit-step" data-arg="${st[0]}"><span class="step-dot">${st[4] ? '✓' : st[1]}</span><span class="step-tx">${st[2]}<span class="en">${st[3]}</span></span></button>`).join('<i class="step-line" aria-hidden="true"></i>')}</div>
