  qs.push({ skill: 'vocab', prompt: hasPic(g) ? `${g[3]} "${g[2]}"` : `📘 ${g[0]}`, hint: 'Pick the Fusha word', right: g[0], opts: shuffle([g[0]].concat(sample(others(g), 3).map((x) => x[0]))) });
