  qs.push(hasPic(f) && pv(f).length >= 3 ? { skill: 'reading', prompt: `📘 ${f[0]}`, hint: 'A Fusha word. Pick its picture', right: f[3], pics: true, opts: shuffle([f[3]].concat(sample(pv(f), 3).map((x) => x[3]))) }
    : { skill: 'reading', prompt: `📘 ${f[0]}`, hint: 'A Fusha word. Pick the same word', right: f[0], opts: shuffle([f[0]].concat(sample(others(f), 3).map((x) => x[0]))) });
  const li = (Math.random() * u.dialogue.length) | 0; const line = u.dialogue[li];
