RENDER.grammar = function renderGrammar() {
  const p = P(); const n = countPrefix(p, 'lesson:');
  $('tab-grammar').innerHTML = `<div class="card stack">
    <div class="section-title row between"><div><h2>🧩 قَوَاعِدُ اللُّغَة</h2><p class="en en-block">${grammarTopics.length} grammar topics, from simple to harder. Open a topic, read the short explanation, then solve the check question.</p></div><span class="pill acc">${n}/${grammarTopics.length} <span class="en" style="color:inherit">solved</span></span></div>
    <div class="grid g2">${grammarTopics.map((t, idx) => { const done = !!p.completed['lesson:' + t.id]; return `<div class="dlg ${done ? 'done' : ''} stack">
      <div class="row between"><span class="pill good">${esc(t.level)} <span class="en" style="color:inherit">${esc(t.levelEn)}</span></span><span class="muted small">درس ${toArabicDigits(idx + 1)}</span></div>
      <h3 style="font-size:1.3rem;font-weight:800">${esc(t.title)}</h3><span class="en">${esc(t.en)}</span>
      <button class="btn ${done ? 'done' : ''}" data-act="lesson-open" data-arg="${t.id}">${done ? '✅ <span class="en">Review</span>' : G('اِبْدَأِ اللُّغْزَ', 'اِبْدَئِي اللُّغْزَ') + ' ← <span class="en">Start puzzle</span>'}</button></div>`; }).join('')}</div></div>`;
};
let lessonState = null;
function openLesson(id) {
  const t = grammarTopics.find((x) => x.id === Number(id)); if (!t) return;
  lessonState = { t, order: shuffle(t.opts.map((o, i) => i)), answered: null }; renderLesson();
}
function renderLesson() {
  const { t, order, answered } = lessonState;
  openModal(`<div class="stack"><div class="row between"><span class="pill good">${esc(t.level)} · <span class="en" style="color:inherit">${esc(t.levelEn)}</span></span><button class="icon-btn" data-act="modal-close" aria-label="Close">✖️</button></div>
    <h2 class="ar-big" style="font-size:1.6rem">${esc(t.title)}</h2><span class="en en-block">${esc(t.en)}</span>
    <p class="en en-block" style="color:var(--ink);font-size:1.05rem;line-height:1.7">${esc(t.explain)}</p>
    <div class="bridge row between"><span class="ar-big" style="font-size:1.3rem">${esc(t.example)}</span><button class="mini" data-act="say" data-text="${esc(t.example)}" data-lang="ar-SA">🔊</button></div><span class="en en-block">${esc(t.exEn)}</span>
    <h3 style="font-weight:800;margin-top:6px">🎯 <span class="en" style="color:var(--ink);font-size:1.05rem">${esc(t.q)}</span></h3>
    <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(150px,1fr))">${order.map((oi) => { let cls = ''; if (answered !== null) { if (oi === 0) cls = 'right'; else if (oi === answered) cls = 'wrong'; } return `<button class="opt ${cls}" data-act="lesson-answer" data-arg="${oi}" ${answered !== null ? 'disabled' : ''} style="justify-content:center">${esc(t.opts[oi])}</button>`; }).join('')}</div>
    ${answered === null ? '' : answered === 0 ? '<div class="feedback good">✅ صَحِيح! <span class="en">Correct! Topic solved.</span></div>' : `<div class="feedback bad row between"><span>❌ <span class="en">Not quite. Read the explanation again.</span></span><button class="btn ghost" data-act="lesson-retry">🔁 <span class="en">Try again</span></button></div>`}</div>`);
}
function lessonAnswer(oi) {
  if (!lessonState || lessonState.answered !== null) return;
  lessonState.answered = oi; sfx(oi === 0 ? 'good' : 'bad'); skillHit('grammar', oi === 0); renderLesson();
  if (oi === 0) { completeOnce('lesson:' + lessonState.t.id, 15, 'grammar', 'Grammar'); if (currentTab === 'grammar') RENDER.grammar(); }
}

