  const start = (e) => { WB.cur = [pos(e)]; WB.strokes.push(WB.cur); if (WB.compare) { WB.compare = false; $('wb-check').classList.add('hidden'); } wbDraw(); };
  const move = (e) => { if (!WB.cur) return; WB.cur.push(pos(e)); wbSchedule(); };
  const end = () => { if (WB.cur && WB.cur.length === 1) WB.cur.push({ x: WB.cur[0].x + 0.001, y: WB.cur[0].y }); WB.cur = null; wbDraw(); };
