  try { ctx.direction = 'rtl'; } catch (e) { /* older browsers */ }
  ctx.font = `700 ${size}px ${fam}`; const m = ctx.measureText(text).width; if (m > w * 0.86) { size *= (w * 0.86) / m; ctx.font = `700 ${size}px ${fam}`; }
  ctx.fillText(text, w / 2, h * 0.7); ctx.restore();
