  ctx.save(); ctx.fillStyle = '#e879a6'; ctx.font = "700 12px 'Nunito','Segoe UI',sans-serif"; ctx.textAlign = 'left'; ctx.fillText(typeof meaningOn === 'function' && meaningOn() ? 'baseline · السَّطْر' : 'السَّطْر', 18, h * 0.7 - 6); ctx.restore();
