function buddyHTML() { const r = round; return `<div class="rd-buddy ${r.answered ? 'talk' : ''}" id="rd-buddy">${falconSVG(r.mood, 'rd-bird')}<div class="rd-bub"><b>${r.buddy[0]}</b><span class="en">${esc(r.buddy[1])}</span></div></div>`; }
