function rdMic() {
  const r = round; const it = r.items[r.i]; const b = $('rd-mic'); if (b) { b.disabled = true; b.innerHTML = `${ICON('ear')} <span class="en">Listening…</span>`; }
  listen(curDialect(), (alts) => {
    const target = it.w.dl || it.w.ar; const best = alts.map((t) => [t, Math.max(sayScore(t, target), similarity(t, target))]).sort((x, y) => y[1] - x[1])[0]; const pct = Math.round(best[1] * 100);
    r.tries++;
    if (pct >= 45 || r.tries >= 2) { it.heard = `<span class="en">I heard:</span> «${esc(best[0])}» · <span class="en">${pct >= 70 ? 'Brilliant!' : pct >= 45 ? 'Nice!' : 'Great try! Practice counts.'}</span>`; rdSaid(pct >= 45, best[1]); }
    else { it.heard = `<span class="en">I heard:</span> «${esc(best[0])}» · <span class="en">Nearly! One more go?</span>`; r.buddy = ['قَرِيب!', 'Ooh, nearly! Try again, slowly.']; r.mood = 'think'; renderRound(); }
  }, (code) => { it.heard = micErrorText(code); renderRound(); });
}
/* ---------- placement as a game: Find your falcon level (10 quick taps) ---------- */
function placementBuild() {
  const qs = [];
  LEVELS.forEach((L) => { const pool = []; UNITS.filter((u) => u.level === L.n).forEach((u) => u.vocab.forEach((v) => pool.push(v)));
    sample(pool, 1).forEach((v) => { const wrong = sample(pool.filter((x) => x !== v), 3); qs.push({ kind: 'vocab', skill: 'vocab', level: L.n, v, right: v[0], opts: shuffle([v].concat(wrong)).map((x) => x[0]) }); }); });
  sample(ALPHA, 2).forEach((a, i) => qs.splice(1 + i * 2, 0, { kind: 'letter', skill: 'letters', a, right: a[1], opts: shuffle([a[1]].concat(sample(ALPHA.filter((x) => x !== a), 3).map((x) => x[1]))) }));
  const lines = []; UNITS.filter((u) => u.level <= 2).forEach((u) => u.dialogue.forEach((l) => lines.push(l)));
  sample(lines, 2).forEach((l) => qs.push({ kind: 'reading', skill: 'reading', l, right: l[3], opts: shuffle([l[3]].concat(sample(lines.filter((x) => x !== l), 3).map((x) => x[3]))) }));
  sample(grammarTopics.filter((g) => g.opts && g.opts.length), 2).forEach((g) => qs.push({ kind: 'grammar', skill: 'grammar', g, right: g.opts[0], opts: shuffle(g.opts.slice()) }));
  return qs;
}
function placementPrompt(q) {
  if (q.kind === 'letter') return `<div class="center"><div class="pl-big ar-letter">${q.a[0]}</div><h3 class="pl-q">مَا اسْمُ هَذَا الحَرْف؟ <span class="en en-block">What's this letter called?</span></h3></div>`;
  if (q.kind === 'reading') return `<div class="center"><div class="pl-read">${esc(q.l[2])}</div><h3 class="pl-q">مَاذَا تَعْنِي؟ <span class="en en-block">What does it mean?</span></h3></div>`;
  if (q.kind === 'grammar') return `<div class="center"><div class="pl-big">${ICON('guess')}</div><h3 class="pl-q en" dir="ltr">${esc(q.g.q)}</h3><p class="en en-block center">A brain teaser. Guessing is fine!</p></div>`;
  return `<div class="center"><div class="pl-big"><span class="emo">${q.v[3]}</span></div><h3 class="pl-q">"${esc(q.v[2])}" <span class="en en-block">Which word is it? Guessing is fine.</span></h3></div>`;
}
function renderPlacement() {
  const s = placement; const q = s.qs[s.i]; const pct = Math.round(100 * s.i / s.qs.length);
  openModal(`<div class="stack placement pl-game">
    <div class="row between"><b class="pl-title">${ICON('compass')} <span>مُسْتَوَى صَقْرِك <span class="en en-block">Find your falcon level</span></span></b><button class="icon-btn" data-act="modal-close" aria-label="Close">✖️</button></div>
    <div class="pl-sky" aria-label="${s.i + 1} of ${s.qs.length}"><div class="pl-fill" style="width:${pct}%"></div><span class="pl-bird" style="inset-inline-start:calc(${pct * 0.9}% - 4px)">${falconSVG('cheer', 'pl-mini', null, '20 4 60 60')}</span></div>
    ${s.i === 0 ? `<p class="en en-block center small">10 quick taps. How high can your falcon fly?</p>` : ''}
    ${placementPrompt(q)}
    <div class="opts two">${q.opts.map((o, i) => `<button class="opt" data-act="placement-answer" data-arg="${i}" ${q.kind === 'reading' || q.kind === 'letter' ? 'dir="ltr"' : ''}><span class="opt-tx ${q.kind === 'reading' || q.kind === 'letter' ? 'en-opt' : ''}">${esc(o)}</span></button>`).join('')}</div>
    <button class="btn ghost" data-act="placement-answer" data-arg="-1">لَسْتُ ${G('مُتَأَكِّداً', 'مُتَأَكِّدَة')} <span class="en">Not sure? Skip</span></button></div>`, null, 'sheet');
}
function placementAnswer(i) {
  const s = placement; const q = s.qs[s.i]; const ok = i >= 0 && q.opts[i] === q.right;
  if (ok && q.kind === 'vocab') s.right[q.level]++;
  const k = s.sk[q.skill] || (s.sk[q.skill] = [0, 0]); k[1]++; if (ok) k[0]++;
  s.i++; sfx(ok ? 'good' : 'tap');
  if (s.i < s.qs.length) { renderPlacement(); return; }
  let level = 4; for (let L = 1; L <= 4; L++) { if (s.right[L] < 1) { level = L; break; } }
  const p = P(); const sk = {}; Object.keys(s.sk).forEach((id) => { sk[id] = s.sk[id][0] / s.sk[id][1]; skillRec(p, id).pl = sk[id]; });
  p.placement = { level, date: dayKey(), detail: s.right, skills: sk }; p.today.focus = null;
  placement = null; saveDB(); modalOnClose = null; closeModal();
  award(20, 'placement', { msg: 'Falcon level found' }); confetti(120);
  const L = LEVELS[level - 1];
  openModal(`<div class="center stack pl-done">${typeof sceneBg === 'function' ? sceneBg('beach', 'cel-scene left') : ''}${falconSVG('trophy', 'lg')}<div class="rw-kick">${ICON('compass')} مُسْتَوَى صَقْرِك <span class="en">Your falcon level</span></div><h2 class="rw-name">${esc(L.ar || '')} <span class="en">${esc(L.en)}</span></h2>
    <p class="en en-block center">Your falcon is ready to fly. Every round gets you higher!</p>
    ${placementSkillSummary(sk)}
    <button class="btn big gold" data-act="modal-close">يَلَّا نَلْعَب! <span class="en">Let's play!</span></button></div>`, () => { switchTab('home'); }, 'sheet');
}
