  if (g.notes && g.notes.length && g.anim < 0) return `<div class="wd-msg note" role="status">${g.notes.map((x) => `<span class="en" dir="ltr"><bdi class="ar-inline">${x.grp}</bdi> count as the same letter here. This word writes <bdi class="ar-inline">${x.real}</bdi>.</span>`).join('<br>')}</div>`;
