    WD.buddy = g.won ? (g.rows.length <= 2 ? ['عَبْقَرِي!', `Wow, in ${g.rows.length}! Are you a word wizard?`] : g.rows.length <= 4 ? ['رَائِع!', `You found it in ${g.rows.length} tries!`] : ['يَا سَلَام!', 'Just in time! Great thinking.']) : ['قَرِيب!', "So close! Now you know a new word. Try another?"];
    if (g.won) { sfx('level'); confetti(140); setTimeout(() => ltSpeak(g.w.ar), 500); } else { sfx('tap'); setTimeout(() => ltSpeak(g.w.ar), 400); }
