/* ---------- a quick 3-letter step inside Play rounds ---------- */
PLAY_GAMES.wordle = { ar: 'كَلِمَة السِّرّ', en: 'Secret word', skill: 'spelling', color: '#22a86a', icon: 'grid', desc: 'Guess the 3-letter word. Colours help!' };
function wdRoundWord(w) {
  if (w && w.ar) { const L = wdLetters(w.ar); if (L.length === 3 && !/\s/.test(w.ar.trim()) && w.em) { const k = wdKey(L); const known = wdData().valid.get(k); return Object.assign({}, known || {}, { ar: w.ar, en: w.en, em: w.em, letters: L, k, n: 3, key: w.key }); } }
  const list = wdData().prac[3]; const p = P(); const met = list.filter((x) => x.key && p.play.met[x.key]); const src = met.length > 3 && Math.random() < 0.5 ? met : list; return src[(Math.random() * src.length) | 0];
}
