  if (!force && Math.random() > wdRoundChance(P())) return items;
  const spots = items.map((it, i) => i).filter((i) => i >= 2 && items[i].kind !== 'meet' && items[i].kind !== 'say' && (!items[i - 1] || items[i - 1].kind !== 'wordle'));
  if (!spots.length) return items; const at = spots[(Math.random() * spots.length) | 0]; items[at] = makeItem('wordle', items[at].w, null); return items;
