const micAllowed = (kid) => !!(kid && consentOf(kid).mic && hasPin());
const cloudAllowed = (kid) => !!(kid && consentOf(kid).cloud && hasPin() && aiAccess());
function addAlert(kind, level) { if (!Array.isArray(DB.settings.alerts)) DB.settings.alerts = []; DB.settings.alerts.push({ kid: currentKid, kind: String(kind).slice(0, 16), level: level === 'high' ? 'high' : 'low', at: new Date().toISOString(), seen: false }); DB.settings.alerts = DB.settings.alerts.slice(-50); saveDB(); refreshAlertDot(); }
const unseenAlerts = () => (Array.isArray(DB.settings.alerts) ? DB.settings.alerts.filter((a) => !a.seen) : []);
