const SCOPE_SUBJECT_HINT = [['science', /(science|علوم|العلوم|solar|planet|space|moon|sun|star|volcano|dinosaur|rain|sky|weather|كوكب|كواكب|الفضاء|القمر|الشمس|نجوم|البركان|ديناصور|المطر|السما)/], ['maths', /(math|number|ضرب|رياضيات|حساب|ارقام)/], ['games', /(roblox|minecraft|fortnite|game|لعبه|روبلوكس|ماينكرافت)/], ['news', /(ronaldo|messi|football|match|sport|رونالدو|ميسي|كوره|مباراه|الماتش)/], ['animals', /(spider|animal|dog|cat|lion|horse|bird|insect|عنكبوت|حيوان|حيوانات|اسد|حصان|طير|حشرات)/], ['coding', /(phone|computer|laptop|tablet|ipad|robot|جوال|موبايل|هاتف|كمبيوتر|ايباد|روبوت)/]];
