  const risk = detectRisk(raw);
  if (risk && HIGH.has(risk.kind)) return { topic: 'safeguarding', subject: risk.kind, by: 'rules' };
  /* v20: grooming (one message or a build-up over the child's earlier turns) is safeguarding, never an off-topic redirect */
