/* v20: pronunciation stars. Azure Speech pronunciation assessment (REST, short audio).
   Locales: the docs list only ar-SA and ar-EG for pronunciation assessment (no ar-AE / ar-LB / ar-SY / ar-JO), and Arabic gets
   word/text scores only (phoneme names are en-US only). So the app checks Fusha (MSA) letters and words with ar-SA, for every dialect.
   The child never sees a number: the score becomes 1-3 stars here, on the server. Audio is passed through and dropped, never stored. */

const PRON_LOCALE = 'ar-SA';
const PRON_MAX_B64 = 700000;
/* the hard letters, each with one Fusha word the child says (the server only assesses these words); [letter, word, en, emoji, painted art key] */
const PRON_CARDS = [
  ['ع', 'عَيْنٌ', 'eye', '👁️', 'ob_eye'], ['ح', 'حَلِيبٌ', 'milk', '🥛', 'ob_milk'], ['خ', 'خُبْزٌ', 'bread', '🍞', 'ob_bread'], ['ق', 'قَمَرٌ', 'moon', '🌙', 'ob_moon'],
  ['ض', 'ضِفْدَعٌ', 'frog', '🐸', 'ob_frog'], ['غ', 'غَيْمَةٌ', 'cloud', '☁️', 'ob_cloud'], ['ص', 'صَقْرٌ', 'falcon', '🦅', 'ob_bird'], ['ط', 'طَائِرَةٌ', 'plane', '✈️', 'ob_plane'],
  ['ظ', 'ظَرْفٌ', 'envelope', '✉️', 'ob_envelope'], ['ذ', 'ذِئْبٌ', 'wolf', '🐺', 'ob_wolf'], ['ث', 'ثَعْلَبٌ', 'fox', '🦊', 'ob_fox']
];
const pronBare = (s) => String(s || '').replace(/[\u064B-\u0652\u0670]/g, '').replace(/[^\u0600-\u06FF]/g, '');
const pronKnownRef = (ref) => PRON_CARDS.some((c) => pronBare(c[1]) === pronBare(ref)); /* PRON_MAX_B64: ~16 s of 16 kHz mono 16-bit WAV */
/* v20b "read it to Sakr": a story sentence that exists in the app (READ_REFS is generated from READ_STORIES), length-capped */
const READ_MAX_CHARS = 160;
const readBare = (s) => String(s || '').replace(/[\u064B-\u0652\u0670\u0640]/g, '').replace(/[^\u0621-\u064A ]/g, ' ').replace(/\s+/g, ' ').trim();
const READ_SET = new Set(READ_REFS);
const pronKnownRead = (ref) => { const b = readBare(ref); return !!b && b.length <= READ_MAX_CHARS && READ_SET.has(b); };
function starsFor(r) {
  if (!r || !(r.recognized)) return 0; /* nothing heard: no stars, just "say it again" */
  const s = Math.min(r.accuracy, r.pron == null ? r.accuracy : r.pron + 6);
  return s >= 85 ? 3 : s >= 65 ? 2 : 1;
}
const b64json = (o) => btoa(unescape(encodeURIComponent(JSON.stringify(o))));
async function assessPron(wavB64, refText, cfg, opts) {
  const read = !!(opts && opts.mode === 'read');
  const ref = String(refText || '').replace(/[^\u0600-\u06FF\s]/g, '').replace(/\s+/g, ' ').trim().slice(0, read ? 200 : 60); if (!ref || !(read ? pronKnownRead(ref) : pronKnownRef(ref))) throw new Error('ref');
  const bin = Uint8Array.from(atob(wavB64), (c) => c.charCodeAt(0));
  const pa = b64json({ ReferenceText: ref, GradingSystem: 'HundredMark', Granularity: 'Word', Dimension: 'Comprehensive', EnableMiscue: read });
  const r = await fetch(`https://${cfg.region}.stt.speech.microsoft.com/speech/recognition/conversation/cognitiveservices/v1?language=${PRON_LOCALE}&format=detailed`, {
    method: 'POST', headers: { 'Ocp-Apim-Subscription-Key': cfg.key, 'Content-Type': 'audio/wav; codecs=audio/pcm; samplerate=16000', 'Pronunciation-Assessment': pa, Accept: 'application/json' }, body: bin, signal: AbortSignal.timeout(12000) });
  if (!r.ok) throw new Error('speech ' + r.status);
  const j = await r.json(); const nb = (j.NBest || [])[0];
  if (j.RecognitionStatus !== 'Success' || !nb) return { stars: 0, heard: false };
  const pa2 = nb.PronunciationAssessment || nb; const acc = +(pa2.AccuracyScore != null ? pa2.AccuracyScore : nb.AccuracyScore || 0); const pron = pa2.PronScore != null ? +pa2.PronScore : null;
  /* with miscue on (reading), Words follows the reference (omissions included) plus insertions: drop insertions to line up with the text */
  const words = (nb.Words || []).filter((w) => ((w.PronunciationAssessment || w).ErrorType || 'None') !== 'Insertion').map((w) => { const a = w.PronunciationAssessment || w; return { ok: (a.AccuracyScore || 0) >= 65 && (a.ErrorType || 'None') === 'None' }; });
  const comp = pa2.CompletenessScore != null ? +pa2.CompletenessScore : null;
  let stars = starsFor({ recognized: true, accuracy: acc, pron }); if (read && comp != null && comp < 75) stars = Math.min(stars, comp < 45 ? 1 : 2); /* skipped words cap the sentence */
  return { stars, heard: true, words_ok: words.map((w) => w.ok) }; /* stars + which words were fine; no numbers */
}

