    const acts = redirectActions(tp.topic, cloud ? tp.subject : null, curDialect(), g).map((a) => (a.type === 'ask' ? Object.assign({}, a, { chips: a.chips.map((c) => Object.assign({}, c, { icon: 'play' })) }) : a));
    if (cloud) { acts.forEach((a) => TT.brain.history.push({ role: 'tutor', text: TB.scrub(a.ar + ' / ' + a.en) })); await ttRun(acts); return; }
