/* v46: until a child's first chat, the default falcon greets with "I'm Sakr" (Meet Sakr). Kept in its own small localStorage key, outside arabicTutor.v2 (no new save field; per device; losing it only means one extra "I'm Sakr"). */
function sakrMet() { try { return JSON.parse(localStorage.getItem('arabicTutor.sakrMet') || '{}') || {}; } catch (e) { return {}; } }
function mhGreetKey() { try { return !falconName(currentKid).custom && !sakrMet()[currentKid] ? 'meet' : 'greet'; } catch (e) { return 'greet'; } }
function sakrMarkMet() { const m = sakrMet(); if (m[currentKid]) return; m[currentKid] = 1; try { localStorage.setItem('arabicTutor.sakrMet', JSON.stringify(m)); } catch (e) { /* */ } }

