/* =========================================================
   ACTIVITY SIGNALS: every activity type sends start and finish, so the falcon always knows what happened and every
   activity comes back to him. Modal activities return when their sheet closes; full-page areas (tabs, the homework
   helper, the guided lesson) show the back-to-falcon button, which calls out once the activity is finished.
   ========================================================= */
const ACT_SIG = { cur: null, last: null, log: [] };
function actStart(kind, info) {
  ACT_SIG.cur = { kind, t: Date.now(), info: info || null, done: null }; ACT_SIG.log.push({ phase: 'start', kind, t: Date.now() }); if (ACT_SIG.log.length > 80) ACT_SIG.log.shift();
  document.dispatchEvent(new CustomEvent('saqqour-activity', { detail: { phase: 'start', kind } }));
}
function actFinish(kind, res) {
  res = res || {}; const cur = ACT_SIG.cur; const k = kind || (cur && cur.kind) || 'activity';
  if (cur && cur.done && !res.force) return; /* one finish per start */
  const sig = { phase: 'finish', kind: k, ok: res.ok == null ? null : !!res.ok, closed: !!res.closed, t: Date.now() };
  if (cur) cur.done = sig; ACT_SIG.last = sig; ACT_SIG.log.push(sig); if (ACT_SIG.log.length > 80) ACT_SIG.log.shift();
  document.dispatchEvent(new CustomEvent('saqqour-activity', { detail: sig }));
  if (MH.act) MH.act.done = sig;
  if (MH.act && (MH.act.tab || MH.act.view) && !res.closed) mhCallBack();
}
/* the back button calls the child home once a full-page activity is done */
function mhCallBack() {
  const b = $('mh-back'); if (!b || b.classList.contains('hidden')) return;
  $('mh-back-t').textContent = mhLine('back_call').ar; b.classList.add('call'); sfx('pop');
}
function mhWrap(name, before, after) {
  const orig = window[name]; if (typeof orig !== 'function') return;
  window[name] = function () { if (before) before.apply(this, arguments); const r = orig.apply(this, arguments); if (after) after.apply(this, [r].concat([].slice.call(arguments))); return r; };
}
/* starts */
mhWrap('openLetter', (ch) => actStart('letter', ch));
mhWrap('openReader', (id) => actStart('story', id));
mhWrap('openWordle', (m) => actStart('wordle', m));
mhWrap('startRound', (k) => actStart('round:' + k));
mhWrap('gameStart', (k) => actStart('game:' + k));
mhWrap('openFalcon', () => actStart('dress'));
mhWrap('openStickers', () => actStart('stickers'));
mhWrap('openBuilder', () => actStart('build'));
mhWrap('openSayIt', () => actStart('sayit'));
mhWrap('startBoost', (id) => actStart('boost:' + id));
mhWrap('placementStart', () => actStart('placement'));
mhWrap('startQuiz', (s) => actStart('quiz', s));
mhWrap('openUnit', (id) => actStart('unit', id));
mhWrap('openLesson', (id) => actStart('grammar', id));
mhWrap('listenStart', () => actStart('listen'));
/* finishes */
mhWrap('roundFinish', null, () => actFinish(null, { ok: true }));
mhWrap('gameFinish', null, (r, kind, success) => { actFinish('game:' + kind, { ok: success }); mhGameBack(); });
mhWrap('readerDone', null, () => actFinish('story', { ok: true }));
mhWrap('readerEnd', null, () => actFinish('story', { ok: null }));
mhWrap('wdFinish', null, () => actFinish('wordle', { ok: true }));
mhWrap('sayitEnd', null, () => actFinish('sayit', { ok: true }));
mhWrap('quizNext', null, () => { if (typeof quiz !== 'undefined' && quiz && quiz.done) actFinish('quiz', { ok: quiz.score >= quiz.qs.length / 2 }); });
mhWrap('placementAnswer', null, () => { if (typeof placement !== 'undefined' && placement === null) actFinish('placement', { ok: true }); });
/* any progress earned inside an activity (builder, tracing, units, dialogues, grammar…) counts as its finish */
mhWrap('award', null, (r, xp) => { if (ACT_SIG.cur && !ACT_SIG.cur.done && xp > 0) actFinish(null, { ok: true }); });
/* a game result (inside the games page) offers the way back to the falcon */
function mhGameBack() {
  if (!MH.act) return; const row = document.querySelector('#tab-games .game-result .row'); if (!row || row.querySelector('.mh-to-falcon')) return;
  const b = document.createElement('button'); b.className = 'btn mh-to-falcon'; b.dataset.act = 'mh-back'; b.innerHTML = `${falconHeadHTML(currentKid, 'sm')}<span>إِلَى صَقْر</span>`; row.appendChild(b);
}

/* ---------- open an activity, then come back ---------- */
function mhOpen(id, fromChip) {
  const d = mhDef(id); const p = P(); MH.delay = 0;
  if (fromChip) { const c = MH.lastChip; if (c) mhKid(c); }
  const cards = [...mhChat().querySelectorAll('.mh-card[data-id="' + id + '"]')]; const card = cards[cards.length - 1];
  if (card) card.classList.add('chosen'); else if (!MH.fromGrid) { const row = mhCards([id]); const c2 = row.querySelector('.mh-card'); if (c2) c2.classList.add('chosen'); }
  mhSay(mhLine('go')); mhSetChips([]);
  MH.act = { id, coins: p.coins, xp: p.xp, tab: d.tab || null, view: !!d.view, look: JSON.stringify(p.falcon), done: null };
  if (d.tab) actStart('area:' + d.tab);
  sfx('whoosh');
  setTimeout(() => {
    if (d.tab) { $('mh').classList.add('hidden'); document.body.classList.remove('mh-on'); $('app').classList.remove('hidden'); MH.inTab = true; _mhSwitchTab(d.tab); MH.inTab = false; mhShowBack(); }
    else d.run();
  }, MH.fast ? 0 : 900);
}
function mhShowBack() { $('mh-back-av').innerHTML = falconHeadHTML(currentKid, 'sm'); $('mh-back-t').textContent = 'صَقْر'; $('mh-back').classList.remove('call'); $('mh-back').classList.remove('hidden'); }
function mhReturn() {
  const a = MH.act; MH.act = null; if (ACT_SIG.cur && !ACT_SIG.cur.done) actFinish(null, { closed: true });
  ACT_SIG.cur = null; if (!a || !currentKid) { mhShow(); return; }
  mhShow(); MH.delay = 0; const p = P(); const dc = p.coins - a.coins; const dx = p.xp - a.xp;
  const changedLook = JSON.stringify(p.falcon) !== a.look; const fin = a.done;
  $('mh').classList.add('react'); setTimeout(() => $('mh').classList.remove('react'), 1400);
  if (a.id === 'dress' && changedLook) { mhAppend(`${falconSVG('happy', 'mh-show-falcon')}`, 'mh-show'); mhSay(mhLine('dressed')); }
  else if (dx > 0 || dc > 0 || (fin && fin.ok)) {
    mhAppend(`${falconSVG('happy', 'mh-show-falcon')}<span class="mh-spark s1" aria-hidden="true">${mhArt('ic2_star')}</span><span class="mh-spark s2" aria-hidden="true">${mhArt('ic2_coin')}</span><span class="mh-spark s3" aria-hidden="true">${mhArt('ic2_spark')}</span>`, 'mh-show');
    mhSay(mhLine('win'), dx > 0 || dc > 0 ? `<div class="mh-reward" aria-label="+${toArabicDigits(Math.max(0, dc))} عُمْلَة">
      <span class="mh-rw coin">${mhArt('ic2_coin')}<b>+${toArabicDigits(Math.max(0, dc))}</b></span><span class="mh-rw pearl">${mhArt('ic2_pearl')}<b>+${toArabicDigits(Math.max(0, dx))}</b></span>
      <span class="mh-rw total">الرَّصِيدُ <b>${toArabicDigits(p.coins)}</b></span></div>` : '');
    if (dc > 0) mhSay(mhLine('coins'));
    sfx('good');
  } else mhSay(mhLine('none'));
  /* next ideas: skip what was just done */
  MH.shown[a.id] = 1; const plan = mhPlan(p).filter((x) => x !== a.id && !(x === 'letter' && a.id === 'letters'));
  const fresh = plan.filter((x) => !MH.shown[x]); const next = (fresh.length ? fresh : plan).slice(0, 2); next.forEach((x) => { MH.shown[x] = 1; });
  mhSay(mhLine('next')); mhCards(next);
  mhSetChips([{ line: mhLine('c_yes'), go: () => mhOpen(next[0], true) }, { line: mhLine('c_other'), go: mhMore }]);
  mhHeader(); const cn = $('mh-coins'); if (dc > 0 && cn) { cn.classList.remove('bump'); void cn.offsetWidth; cn.classList.add('bump'); }
}

/* ---------- the guided lesson (the tutor screen) as one more activity ---------- */
