    <div class="mh-gridx">${ids.map((id) => { const d = mhDef(id); const k = 'g' + (++MH.n); MH.cards[k] = id; return `<button class="mh-gt ${id === 'homework' ? 'hw-tile' : ''}" data-act="mh-open" data-arg="${k}" data-from="grid" data-id="${id}">${mhTile(d)}<b>${esc(d.title)}</b><span class="en">${esc(d.en)}</span></button>`; }).join('')}</div>
