      <div class="jv-loot"><span class="jv-loot-c">${mhArt('ic2_coin')}<b>+${toArabicDigits(r.coins)}</b></span>${s ? `<span class="jv-loot-s">${stickerSVG(s.id)}<b lang="ar">${esc(s.ar)}</b><span class="en">${esc(s.en || '')}</span></span>` : ''}</div>
