  try { let img = file; if (typeof hwxIsPdf === 'function' && hwxIsPdf(file)) { const r = await hwxPdfPages(file); img = r.pages[0]; } ws = await spExtract(await hwPrep(img), 'class'); } catch (e) { ws = null; }
