function cwQueue() { openModal(`<div class="stack sp"><div class="row between"><h2 lang="ar"><span class="emo" aria-hidden="true">👪</span> قَائِمَةُ كَلِمَاتِ الصَّفّ</h2>${spX()}</div><p class="sp-sub" lang="ar">خَمْسُ كَلِمَاتٍ كُلَّ أُسْبُوع. ✓ = تَعَلَّمَهَا الطِّفْل.</p>${cwQueueHTML()}<button class="btn soft" data-act="cw-open">رُجُوع</button></div>`, null, 'sheet'); }
