  if (who === 'gm' || who === 'gf' || who === 'p') return { g: who === 'p' ? 'p' : who.slice(1), slot: null, name: '' };
  const slot = who && (ACC.map || {})[who] ? ACC.map[who] : who && DB.profiles[who] ? who : null;
  if (slot && DB.profiles[slot]) return { g: DB.profiles[slot].g === 'f' ? 'f' : 'm', slot, name: DB.profiles[slot].nick || '' };
