/* ---------- letter tracing sheet ---------- */
const PR32_FORM = { isolated: ['وَحْدَهُ', 'Alone'], initial: ['فِي أَوَّلِ الكَلِمَةِ', 'Start'], medial: ['فِي وَسَطِ الكَلِمَةِ', 'Middle'], final: ['فِي آخِرِ الكَلِمَةِ', 'End'] };
