  const W = 150, H = 32, base = 21; const cells = []; let x = W - slotW / 2;
  for (let i = 0; i < n; i++) {
    const solid = i === 0; const empty = i >= n - 1 && n > 2;
    if (!empty && glyph) cells.push(`<text x="${x.toFixed(1)}" y="${base}" text-anchor="middle" direction="rtl" font-size="${size}" class="${solid ? 'pr-g-solid' : 'pr-g-dash'}">${esc(glyph)}</text>`);
    x -= slotW; }
