  const forms = formsOf(ch); const seen = new Set(); const rows = forms.filter(([k, g]) => { if (seen.has(g)) return false; seen.add(g); return true; });
  const nonJ = R_JOIN.has(ch) && ch !== 'ة';
  const pic = L[6] ? (typeof objArtHTML === 'function' ? objArtHTML(L[6], L[4], 'pr-pic-art') : '') || `<span class="pr-pic-emo">${L[6]}</span>` : '';
  const ins = pr32G(c, 'تَتَبَّعِ الحَرْفَ عَلَى الخُطُوطِ المُنَقَّطَةِ، ثُمَّ اكْتُبْهُ وَحْدَكَ فِي المَكَانِ الفَارِغِ.', 'تَتَبَّعِي الحَرْفَ عَلَى الخُطُوطِ المُنَقَّطَةِ، ثُمَّ اكْتُبِيهِ وَحْدَكِ فِي المَكَانِ الفَارِغِ.', 'تَتَبَّعُوا الحَرْفَ عَلَى الخُطُوطِ المُنَقَّطَةِ، ثُمَّ اكْتُبُوهُ وَحْدَكُمْ فِي المَكَانِ الفَارِغِ.');
