  const note = nonJ ? `<p class="pb pr-note">💡 هَذَا الحَرْفُ لَا يَتَّصِلُ بِالحَرْفِ الَّذِي بَعْدَهُ.${pr32EnHTML('This letter never joins the letter after it.')}</p>` : '';
