/* 2. loading pulse on the speaker that was tapped */
function v53Busy(on) { try { const b = V53.tapEl; if (!b) return; b.classList.toggle('v53-wait', !!on); if (on) setTimeout(() => b.classList.remove('v53-wait'), 9000); } catch (e) { /* */ } }
